// Open-source knowledge bases: the two public repositories that hold over a
// decade of study notes, solved problems, and runnable code. The home page
// section, /open-source, the per-repository pages, JSON-LD, llms.txt, the
// search corpus, and the MCP server all read from here.
//
// Every number below is taken from the repository's own README, which each
// repository regenerates or checks in CI (The Quant Prep's syllabus table is
// generated by `./qp index` and `./qp check` fails when it is stale). Re-sync
// them from the READMEs when the repositories grow; stars and forks are read
// live from the GitHub API instead.

import { GITHUB_LOGIN } from './github';

export const OPEN_SOURCE_PATH = '/open-source';

export interface KbStat {
  value: string;
  label: string;
}

export interface KbPillar {
  title: string;
  detail: string;
  // Repository-relative path of the folder or file the pillar links to.
  path: string;
}

export interface KbPath {
  role: string;
  route: string;
}

export interface KnowledgeBase {
  slug: string;
  name: string;
  repoName: string; // GitHub repository name under GITHUB_LOGIN
  tagline: string;
  summary: string;
  // <title> (the layout appends the author) and meta description, written
  // for the searches the repository answers.
  seoTitle: string;
  seoDescription: string;
  since: number; // year the repository went public
  license: 'MIT';
  // Who it is written for, phrased as roles.
  audience: string[];
  // Headline numbers from the repository README.
  stats: KbStat[];
  pillars: KbPillar[];
  paths: KbPath[];
  // Why a reader can rely on it; each point is checkable in the repository.
  standards: string[];
  quickStart: string;
  // For schema.org `teaches` and the page keywords.
  topics: string[];
  languages: string[];
  // Firms with a dedicated interview guide (The Quant Prep only).
  firms?: { name: string; path: string }[];
}

