export const kbPath = (kb: Pick<KnowledgeBase, 'slug'>) => `${OPEN_SOURCE_PATH}/${kb.slug}`;
export const repoUrl = (kb: Pick<KnowledgeBase, 'repoName'>) => `https://github.com/${GITHUB_LOGIN}/${kb.repoName}`;

// Link to a folder or file inside the repository. GitHub serves both under
// /tree/ and redirects files there to /blob/, so one form works for either.
export function repoFileUrl(kb: Pick<KnowledgeBase, 'repoName'>, path: string): string {
  const encoded = path.split('/').map(encodeURIComponent).join('/');
  return `${repoUrl(kb)}/tree/main/${encoded}`;
}

export function findKnowledgeBase(slug: string): KnowledgeBase | undefined {
  return KNOWLEDGE_BASES.find((kb) => kb.slug === slug);
}

// ---------------------------------------------------------------------------
// Live repository numbers. Stars and forks change daily, so they are read
// from the GitHub API with the same six-hour revalidation as the home page
// stats. A failed or malformed response hides the numbers instead of
// showing stale or wrong ones.

export interface RepoStats {
  stars: number;
  forks: number;
  pushedAt: string;
}

const REVALIDATE_SECONDS = 6 * 60 * 60;

const isCount = (value: unknown): value is number => typeof value === 'number' && Number.isInteger(value) && value >= 0;

export function parseRepoStats(raw: unknown): RepoStats | null {
  if (typeof raw !== 'object' || raw === null) return null;
  const { stargazers_count: stars, forks_count: forks, pushed_at: pushedAt } = raw as Record<string, unknown>;
  if (!isCount(stars) || !isCount(forks)) return null;
  if (typeof pushedAt !== 'string' || Number.isNaN(Date.parse(pushedAt))) return null;
  return { stars, forks, pushedAt };
}

export async function getRepoStats(kb: Pick<KnowledgeBase, 'repoName'>): Promise<RepoStats | null> {
  const url = `https://api.github.com/repos/${GITHUB_LOGIN}/${kb.repoName}`;
  try {
    const response = await fetch(url, {
      headers: { accept: 'application/vnd.github+json', 'user-agent': 'shreejitverma.com' },
      next: { revalidate: REVALIDATE_SECONDS },
    });
    if (!response.ok) {
      console.warn(`Repository stats unavailable: ${url} returned ${response.status}`);
      return null;
    }
    const stats = parseRepoStats(await response.json());
    if (!stats) console.warn(`Repository stats rejected: ${url} failed validation`);
    return stats;
  } catch (error) {
    console.warn(`Repository stats unavailable: ${url}`, error);
    return null;
  }
}

// Stats for every knowledge base, keyed by slug; a missing key means the
// numbers could not be loaded.
export async function getAllRepoStats(): Promise<Record<string, RepoStats>> {
  const entries = await Promise.all(KNOWLEDGE_BASES.map(async (kb) => [kb.slug, await getRepoStats(kb)] as const));
  return Object.fromEntries(entries.filter((entry): entry is readonly [string, RepoStats] => entry[1] !== null));
}
